interface Comment { id: string; body: string; createdAt: Date }
type CommentDTO = { id: string; body: string; createdAt: Date };

async function listComments(threadId: string): Promise<Comment[]> {
  const rows = await dbQuery('select * from comments where thread_id = $1', [threadId]);
  return rows as Comment[];
}

function toDTO(c: Comment): CommentDTO {
  return { id: c.id, body: c.body, createdAt: c.createdAt };
}

diff.code:
const Comment = z.object({
  id: z.string().uuid(),
  body: z.string().min(1),
  createdAt: z.coerce.date(),
});
type Comment = z.infer<typeof Comment>;

interface CreateBody { body: string; authorId: string }

async function createComment(req: { body: unknown }): Promise<Comment> {
  const input = req.body as CreateBody;
  const row = await db.insert('comments', {
    body: input.body,
    author_id: input.authorId,
  });
  return row as Comment;
}
